package com.bank.paginate;

import java.util.ArrayList;
import java.util.List;

// Simulates an AWS list API capped at PAGE_SIZE items per response.
public class PagedRegistry {
    private static final int PAGE_SIZE = 2;
    private final List<Resource> all;

    public PagedRegistry(List<Resource> all) {
        this.all = all;
    }

    public Page describe(String token) {
        int start = token == null ? 0 : Integer.parseInt(token);
        int end = Math.min(start + PAGE_SIZE, all.size());
        List<Resource> slice = new ArrayList<>(all.subList(start, end));
        String next = end < all.size() ? String.valueOf(end) : null;
        return new Page(slice, next);
    }
}
