package com.bank.paginate;

import java.util.List;
import java.util.logging.Logger;

// BUGGY: reads only the first page, ignores nextToken. Passes in small accounts.
public class FirstPageOnlyReader {
    private static final Logger log = Logger.getLogger(FirstPageOnlyReader.class.getName());
    private final PagedRegistry registry;

    public FirstPageOnlyReader(PagedRegistry registry) {
        this.registry = registry;
    }

    public int countUntagged() {
        Page page = registry.describe(null);                 // ONE call only
        long untagged = page.getItems().stream().filter(r -> !r.isTagged()).count();
        log.warning(() -> "[BUGGY] first-page-only untagged=" + untagged
            + " (nextToken ignored: " + page.getNextToken() + ")");
        return (int) untagged;
    }
}
