package com.bank.paginate;

import java.util.List;
import java.util.logging.Logger;

// CORRECT: follows nextToken until null (what a Boto3 paginator does for you).
public class PaginatedReader {
    private static final Logger log = Logger.getLogger(PaginatedReader.class.getName());
    private final PagedRegistry registry;

    public PaginatedReader(PagedRegistry registry) {
        this.registry = registry;
    }

    public int countUntagged() {
        int untagged = 0;
        int pageNum = 0;
        String token = null;
        do {
            Page page = registry.describe(token);
            pageNum++;
            long pageUntagged = page.getItems().stream().filter(r -> !r.isTagged()).count();
            untagged += pageUntagged;
            final int pn = pageNum;
            log.info(() -> "[PAGINATED] page " + pn + " items=" + page.getItems().size()
                + " untaggedSoFar=" + /* running */ "...");
            token = page.getNextToken();
        } while (token != null);                               // loop until done
        final int total = untagged;
        log.info(() -> "[PAGINATED] COMPLETE untagged across all pages=" + total);
        return untagged;
    }
}
