package com.bank.paginate;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.*;

public class PaginationDemo {
    private static final Logger log = Logger.getLogger(PaginationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Large account: 7 instances, 4 untagged, but page size is only 2.
        List<Resource> all = new ArrayList<>(List.of(
            new Resource("i-01", true),  new Resource("i-02", false),
            new Resource("i-03", false), new Resource("i-04", true),
            new Resource("i-05", false), new Resource("i-06", true),
            new Resource("i-07", false)));
        PagedRegistry registry = new PagedRegistry(all);

        log.info("Compliance scan — counting UNTAGGED instances (true answer = 4)");
        int buggy = new FirstPageOnlyReader(registry).countUntagged();
        int correct = new PaginatedReader(registry).countUntagged();
        log.severe(() -> "BUGGY reported " + buggy + " untagged — MISSED "
            + (correct - buggy) + " because it ignored pagination!");
    }
}
